import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    s = lines[0].strip()
    if len(lines) > 1:
        k = int(lines[1].strip())
    else:
        return

    if len(s) < k:
        print("impossible")
    else:
        unique_count = len(set(s))
        needed = max(0, k - unique_count)
        print(needed)

if __name__ == "__main__":
    main()
